args.command:
/bin/bash -lc "cat > /tmp/tempo-browser-check/check.mjs <<'EOF'
import { chromium } from 'playwright';
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
const errors = [];
page.on('pageerror', error => errors.push(error.message));
await page.goto('http://localhost:5174', { waitUntil: 'networkidle' });
await page.screenshot({ path: '/tmp/tempo-desktop.png', fullPage: true });
if (await page.locator('main section').count() "'!== 3) throw new Error('"'Expected three sections');
if (await page.locator('button').count() "'!== 1) throw new Error('"'Expected one CTA');
await page.getByRole('button', { name: 'Попробовать в деле' }).click();
await page.waitForTimeout(1200);
if (await page.getByRole('timer').textContent() === '00:00:00') throw new Error('Timer did not advance');
await page.getByRole('button', { name: 'Остановить таймер' }).click();
await page.getByRole('button', { name: 'Попробовать ещё раз' }).waitFor();
for (const width of [320, 390, 768, 1440]) {
  await page.setViewportSize({ width, height: 900 });
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth);
  if (overflow) throw new Error("'`Overflow at ${width}px`);
}
await page.setViewportSize({ width: 390, height: 844 });
await page.screenshot({ path: '"'/tmp/tempo-mobile.png', fullPage: true });
if (errors.length) throw new Error(errors.join('\\n'));
console.log('PASS: three sections, one CTA, timer start/advance/stop, responsive widths 320/390/768/1440, no browser errors.');
await browser.close();
EOF"

